BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. Case C: unknown destination — An gets her 300 back | Trường hợp C: người nhận không tồn tại — An được hoàn 300'; END
